}.generator-placeholder{padding:14px;background:#f6f8f4;border:1px dashed #cbd7c9;border-radius:7px;color:#77877b;font-size:11px;line-height:1.7}footer{max-width:1400px;margin:18px auto 0;padding:14px 0;border-top:1px solid #d8e1d6;color:#7a887d;font-size:10px;line-height:1.7}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:600px){.workshop{padding:14px}.panel{padding:14px}.previews{grid-template-columns:1fr}}
